1	// Write side of the notes navigation slice.
2	import { useCallback, type RefObject } from "react";
3	
4	import * as api from "@/features/notes/api/notes-api";
5	import {
6	  ARCHIEVE_FOLDER_PATH,
7	  FEED_FOLDER_PATH,
8	  isSystemFolder,
9	} from "@typenotes/shared/constants";
10	import { confirmAction, focusNoScroll } from "@/shared/lib/dom";
11	import { getNoteParentPath } from "@typenotes/shared/notes";
12	import type { ProfileSyncSettings } from "@typenotes/shared/types";
13	import { applyFolderRenameToSelection, collectNotesForFlattening } from "../model/notes-tree-model";
14	import { findNode } from "@/features/notes/navigation/model/tree-ops";
15	import type { FolderNode } from "@typenotes/shared/types";
16	
17	type UseNotesTreeActionsArgs = {
18	  tree: FolderNode | null;
19	  syncSettings: ProfileSyncSettings;
20	  refreshTree: () => Promise<void>;
21	  rightPaneRef: RefObject<HTMLDivElement | null>;
22	  selectedFolders: Set<string>;
23	  setSelectedFolders: React.Dispatch<React.SetStateAction<Set<string>>>;
24	  setLastSelectedFolder: (path: string) => void;
25	  activeFolder: string;
26	  setActiveFolder: (path: string) => void;
27	  setSelectedNotes: React.Dispatch<React.SetStateAction<Set<string>>>;
28	  setLastSelectedNote: (path: string) => void;
29	  activeNote: string | null;
30	  setActiveNote: (path: string | null) => void;
31	  clearDraft: () => void;
32	  clearNote: () => void;
33	  renamingFolder: string | null;
34	  setRenamingFolder: (path: string | null) => void;
35	  renameValue: string;
36	  setRenameValue: (value: string) => void;
37	};
38	
39	export function useNotesTreeActions({
40	  tree,
41	  syncSettings,
42	  refreshTree,
43	  rightPaneRef,
44	  selectedFolders,
45	  setSelectedFolders,
46	  setLastSelectedFolder,
47	  activeFolder,
48	  setActiveFolder,
49	  setSelectedNotes,
50	  setLastSelectedNote,
51	  activeNote,
52	  setActiveNote,
53	  clearDraft,
54	  clearNote,
55	  renamingFolder,
56	  setRenamingFolder,
57	  renameValue,
58	  setRenameValue,
59	}: UseNotesTreeActionsArgs) {
60	  const createNewNote = useCallback(
61	    async (
62	      preferredFolderPath?: string,
63	      initialContent = "",
64	      targetTimestampMs?: number
65	    ) => {
66	      const treeSnapshot = tree ?? (await api.getTree());
67	      const initialFolderPath = preferredFolderPath?.trim() || FEED_FOLDER_PATH;
68	      const targetNode =
69	        findNode(treeSnapshot, initialFolderPath) || findNode(treeSnapshot, FEED_FOLDER_PATH);
70	      if (!targetNode) return null;
71	      const folderPath = targetNode.path;
72	      const created = await api.createNote(
73	        folderPath,
74	        initialContent,
75	        targetTimestampMs,
76	        syncSettings.noteFileNameFormat
77	      );
78	      const path = created.path;
79	      await refreshTree();
80	
81	      // New note creation is a workflow, not just a write: refresh the tree,
82	      // sync selection, and hand focus to the editor in one pass.
83	      setSelectedFolders(new Set([folderPath]));
84	      setLastSelectedFolder(folderPath);
85	      setActiveFolder(folderPath);
86	      setSelectedNotes(new Set([path]));
87	      setLastSelectedNote(path);
88	      setActiveNote(path);
89	      clearDraft();
90	
91	      requestAnimationFrame(() => {
92	        const editorElement =
93	          rightPaneRef.current?.querySelector<HTMLElement>(
94	            ".tiptap-content[contenteditable='true']"
95	          ) || rightPaneRef.current;
