443	          dragging: movingNotes,
444	          over: overData.path,
445	          noteOrder,
446	          folderOrder,
447	        });
448	        await setOrder({
449	          parent: parentNode.path,
450	          folderOrder,
451	          noteOrder,
452	        });
453	        await refreshTree();
454	      }
455	    },
456	    [
457	      activeNote,
458	      clearNote,
