3	import { useNoteOpener } from "@/app/hooks/use-note-opener";
4	import { useSelection } from "@/app/state/selection-store";
5	import { DesktopAppShell } from "@/desktop/desktop-app-shell";
6	import { CommandPalette } from "@/features/command-palette/components/command-palette";
7	import { useHandwriting } from "@/features/handwriting/hooks/handwriting-context";
8	import { useRecordings } from "@/features/recording/hooks/recordings-context";
