14	  const [desktopAppMode, setDesktopAppMode] = useState<AppMode>("notes");
15	  const [activeSettingsSection, setActiveSettingsSection] =
16	    useState<SettingsSectionId>("general");
17	  const handwritingInputRef = useRef<HTMLInputElement | null>(null);
18	
19	  const activeFolder = useSelection((state) => state.activeFolder);
20	  const { isRecordingAudio, startRecording } = useRecordings();
