31	      console.error("[handwriting] import failed", error);
32	    });
33	  };
34	
35	  return (
36	    <>
37	      <input
38	        ref={handwritingInputRef}
39	        type="file"
40	        accept="image/png,image/jpeg,image/webp,image/gif"
41	        hidden
42	        onChange={onHandwritingImportChange}
43	      />
44	      <CommandPalette
45	        onOpenSettings={(section) => {
46	          setActiveSettingsSection(section);
47	          setDesktopAppMode("settings");
48	        }}
49	        onOpenFeed={() => openPinnedFolder(FEED_FOLDER_PATH)}
50	        onOpenArchive={() => openPinnedFolder(ARCHIEVE_FOLDER_PATH)}
51	        onNewRecording={() => {
52	          if (!isRecordingAudio) {
53	            void startRecording(activeFolder || undefined);
54	          }
55	        }}
56	        onImportHandwriting={() => handwritingInputRef.current?.click()}
57	      />
58	      <DesktopAppShell
59	        appMode={desktopAppMode}
60	        onAppModeChange={setDesktopAppMode}
61	        activeSettingsSection={activeSettingsSection}
62	        onSettingsSectionChange={setActiveSettingsSection}
63	        onImportHandwriting={() => handwritingInputRef.current?.click()}
64	        onOpenPinnedFolder={openPinnedFolder}
65	      />
66	    </>
67	  );
68	}
