1	import { FEED_FOLDER_PATH, isSystemFolder } from "@typenotes/shared/constants";
2	import type { FolderNode, NoteEntry, VisibleNavigationItem } from "@typenotes/shared/types";
3	import type { TreeItem } from "@/features/notes/navigation/model/types";
4	import type { FlattenedItem } from "@/features/notes/navigation/model/types";
5	import { collectAllNotes } from "@typenotes/shared/notes";
6	import { findNode } from "@/features/notes/navigation/model/tree-ops";
7	import type { NotePreview } from "@typenotes/shared/format";
8	
9	// Pure helpers for the notes navigation view. Keep the render rules here so
10	// components stay dumb and the state hook can stay mostly orchestration.
11	type PreviewSourceInput = {
12	  activeFolder: string;
13	  notes: NoteEntry[];
14	  feedNotes: NoteEntry[];
15	  allNotes: NoteEntry[];
16	  shouldNestNotesInNavigation: boolean;
17	};
18	
19	export function selectPreviewSourceNotes({
20	  activeFolder,
21	  notes,
22	  feedNotes,
23	  allNotes,
24	  shouldNestNotesInNavigation,
25	}: PreviewSourceInput): NoteEntry[] {
26	  if (activeFolder === FEED_FOLDER_PATH) {
27	    return feedNotes;
28	  }
29	  if (!shouldNestNotesInNavigation) {
30	    return notes;
31	  }
32	  // Nested navigation shows every folder's notes inline, so warm the vault.
33	  return allNotes;
34	}
35	
36	export function buildVisibleNavigationItems(
37	  treeData: TreeItem[],
38	  expanded: Set<string>,
39	  shouldNestNotesInNavigation: boolean
40	): VisibleNavigationItem[] {
41	  if (!shouldNestNotesInNavigation) {
42	    return [];
43	  }
44	
45	  const items: VisibleNavigationItem[] = [];
46	
47	  // Nested navigation renders folders and notes in one flat list, but only for
48	  // the expanded branches the current layout actually wants to show.
49	  const walk = (nodes: TreeItem[], parentId: string | null) => {
50	    nodes.forEach((node) => {
51	      items.push({
52	        type: "folder",
53	        id: node.id,
54	        parentId,
55	      });
56	
57	      const notesInNode = node.notes || [];
58	      const hasNestedItems = node.children.length > 0 || notesInNode.length > 0;
59	      if (!hasNestedItems || !expanded.has(node.id)) {
60	        return;
61	      }
62	
63	      notesInNode.forEach((note) => {
64	        items.push({
65	          type: "note",
66	          id: note.path,
67	          parentId: node.id,
68	        });
69	      });
70	
71	      walk(node.children, node.id);
72	    });
73	  };
74	
75	  walk(treeData, null);
76	  return items;
77	}
78	
79	type RenamedSelection = {
80	  activeFolder: string;
81	  selectedFolders: Set<string>;
82	  selectedFolderChanged: boolean;
83	};
84	
85	export function applyFolderRenameToSelection(
86	  currentActiveFolder: string,
87	  currentSelectedFolders: Set<string>,
88	  oldPath: string,
89	  newPath: string
90	): RenamedSelection {
91	  const nextSelectedFolders = new Set(currentSelectedFolders);
92	  let selectedFolderChanged = false;
93	
94	  if (nextSelectedFolders.has(oldPath)) {
95	    nextSelectedFolders.delete(oldPath);
96	    nextSelectedFolders.add(newPath);
97	    selectedFolderChanged = true;
98	  }
99	
100	  return {
101	    activeFolder: currentActiveFolder === oldPath ? newPath : currentActiveFolder,
102	    selectedFolders: nextSelectedFolders,
103	    selectedFolderChanged,
104	  };
105	}
106	
107	export function buildNotePreviews(notes: NoteEntry[], previews: Record<string, NotePreview>) {
108	  const next: Record<string, NotePreview> = {};
109	  notes.forEach((note) => {
