    appMode,
    createNewNote,
    deleteSelectedNotes,
    decreaseEditorFontSize,
    foldersPanelRef,
    increaseEditorFontSize,
    middlePaneRef,
    resetEditorFontSize,
    rightPaneRef,
    lockAppNow,
    setSidebarCollapsed,
    shouldNestNotesInNavigation,
    sidebarCollapsed,
    lastLeftPaneFocusRef,
  ]);
}

