const makeDeps = (
  overrides: Partial<NavigateVisibleItemsDeps> = {}
): NavigateVisibleItemsDeps & {
  expand: ReturnType<typeof vi.fn>;
  collapse: ReturnType<typeof vi.fn>;
  selectFolder: ReturnType<typeof vi.fn>;
  selectNote: ReturnType<typeof vi.fn>;
} => ({
  items: buildVisibleNavigationItems(tree, new Set(["personal"]), true),
  preferredIds: [],
  expanded: new Set(["personal"]),
  hasNestedItems: (id) => id === "personal" || id === "personal/journal",
  expand: vi.fn(),
  collapse: vi.fn(),
  selectFolder: vi.fn(),
  selectNote: vi.fn(),
